import{_ as i,a as s,b as a}from"./chunks/taux-fixe-ajustements.mlNDZfoW.js";import{_ as o,c as n,o as r,ae as t}from"./chunks/framework.DBgX5bsf.js";const h=JSON.parse('{"title":"Configuration des Modes de Livraison dans Drupal Commerce","description":"","frontmatter":{},"headers":[],"relativePath":"fr/docs/commerce/livraison.md","filePath":"fr/docs/commerce/livraison.md"}'),d={name:"fr/docs/commerce/livraison.md"};function l(u,e,c,p,m,f){return r(),n("div",null,e[0]||(e[0]=[t('<h1 id="configuration-des-modes-de-livraison-dans-drupal-commerce" tabindex="-1">Configuration des Modes de Livraison dans Drupal Commerce <a class="header-anchor" href="#configuration-des-modes-de-livraison-dans-drupal-commerce" aria-label="Permalink to &quot;Configuration des Modes de Livraison dans Drupal Commerce&quot;">​</a></h1><p>L&#39;environnement de livraison est préconfiguré avec des méthodes de livraison fictives. Ces méthodes peuvent être modifiées, supprimées ou complétées par de nouvelles options selon vos besoins. La configuration des modes de livraison s&#39;effectue dans le menu <code>Configuration</code> -&gt; <code>Commerce</code> -&gt; <code>Expédition</code>.</p><p><img src="'+i+'" alt="Gestion des modes de livraison"></p><h2 id="champs-essentiels-pour-la-configuration-d-un-mode-de-livraison" tabindex="-1">Champs Essentiels pour la Configuration d&#39;un Mode de Livraison <a class="header-anchor" href="#champs-essentiels-pour-la-configuration-d-un-mode-de-livraison" aria-label="Permalink to &quot;Champs Essentiels pour la Configuration d&#39;un Mode de Livraison&quot;">​</a></h2><p>Les éléments clés à renseigner pour configurer un mode de livraison sont les suivants :</p><ul><li><strong>Nom</strong> : Identifiant du mode de livraison (visible uniquement par l&#39;administrateur).</li><li><strong>Plugin</strong> : Type de mode de livraison.</li><li><strong>Rate label</strong> : Libellé du mode de livraison (affiché au client).</li><li><strong>Rate amount</strong> : Montant des frais de livraison.</li><li><strong>Activé</strong> : Statut du mode de livraison (actif ou inactif).</li></ul><h2 id="types-de-modes-de-livraison" tabindex="-1">Types de Modes de Livraison <a class="header-anchor" href="#types-de-modes-de-livraison" aria-label="Permalink to &quot;Types de Modes de Livraison&quot;">​</a></h2><p>Deux types de modes de livraison sont disponibles :</p><ol><li><strong>Taux Fixe</strong></li><li><strong>Taux Fixe Appliqué par Article</strong></li></ol><h3 id="_1-taux-fixe" tabindex="-1">1. Taux Fixe <a class="header-anchor" href="#_1-taux-fixe" aria-label="Permalink to &quot;1. Taux Fixe&quot;">​</a></h3><p>Le mode de livraison <strong>Taux Fixe</strong> (ou <em>Flat Rate</em> en anglais) applique des frais de livraison fixes, indépendamment du nombre d&#39;articles commandés, du poids de la commande ou d&#39;autres facteurs. Le coût de livraison reste identique pour toutes les commandes. Cette option peut être ajustée pour offrir une plus grande flexibilité. Par exemple, il est possible de définir des frais de livraison distincts pour différentes zones géographiques, en fonction du poids, de la quantité de produits, etc.</p><h3 id="_2-taux-fixe-applique-par-article" tabindex="-1">2. Taux Fixe Appliqué par Article <a class="header-anchor" href="#_2-taux-fixe-applique-par-article" aria-label="Permalink to &quot;2. Taux Fixe Appliqué par Article&quot;">​</a></h3><p>Le mode de livraison <strong>Taux Fixe Appliqué par Article</strong> (ou <em>Flat Rate per Item</em> en anglais) applique des frais de livraison fixes pour chaque article commandé. Le coût de livraison est donc proportionnel au nombre d&#39;articles. Cette option peut également être personnalisée pour s&#39;adapter à des critères spécifiques, tels que la zone de livraison, le poids ou la quantité de produits.</p><h2 id="personnalisation-des-frais-de-livraison" tabindex="-1">Personnalisation des Frais de Livraison <a class="header-anchor" href="#personnalisation-des-frais-de-livraison" aria-label="Permalink to &quot;Personnalisation des Frais de Livraison&quot;">​</a></h2><h3 id="ajustement-en-fonction-des-criteres-utilisateur" tabindex="-1">Ajustement en Fonction des Critères Utilisateur <a class="header-anchor" href="#ajustement-en-fonction-des-criteres-utilisateur" aria-label="Permalink to &quot;Ajustement en Fonction des Critères Utilisateur&quot;">​</a></h3><p>Les frais de livraison peuvent être ajustés en fonction de critères liés à l&#39;utilisateur. Par exemple :</p><ul><li><strong>Adresse de Facturation</strong> : Définir des frais de livraison variables selon l&#39;adresse de facturation.</li><li><strong>Adresse de Livraison</strong> : Définir des frais de livraison variables selon l&#39;adresse de livraison.</li></ul><p><img src="'+s+'" alt="Ajustement en fonction de l&#39;utilisateur"></p><h3 id="ajustement-en-fonction-des-criteres-de-livraison" tabindex="-1">Ajustement en Fonction des Critères de Livraison <a class="header-anchor" href="#ajustement-en-fonction-des-criteres-de-livraison" aria-label="Permalink to &quot;Ajustement en Fonction des Critères de Livraison&quot;">​</a></h3><p>Les frais de livraison peuvent également être ajustés en fonction de critères spécifiques à la commande, tels que :</p><ul><li><strong>Shipment Quantity</strong> : Définir des frais de livraison variables en fonction de la quantité d&#39;articles commandés.</li><li><strong>Shipment Weight</strong> : Définir des frais de livraison variables en fonction du poids total de la commande.</li></ul><p><img src="'+a+'" alt="Ajustement des frais de livraison"></p>',22)]))}const x=o(d,[["render",l]]);export{h as __pageData,x as default};
